namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
    public int RatingCount => Ratings.Count;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you going" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and indulgent finishes" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Icon = "🍹", Description = "Refreshing beverages and cocktails" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "Pinch of salt", "Butter for cooking"],
            Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs and milk together, then combine with dry mix.", "Heat a buttered pan over medium heat.", "Pour ¼ cup batter per pancake.", "Cook until bubbles form, flip, and cook until golden."],
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, trendy, and packed with healthy fats.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Lemon juice", "Red pepper flakes", "Salt and pepper", "Optional: poached egg"],
            Steps = ["Toast the bread until golden and crisp.", "Mash avocado with lemon juice, salt, and pepper.", "Spread onto toast and sprinkle with red pepper flakes.", "Top with a poached egg if desired."],
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp, tangy classic that never goes out of style.",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "Grilled chicken (optional)"],
            Steps = ["Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Add croutons and shaved parmesan.", "Top with grilled chicken if desired."],
            Ratings = [4, 4, 3, 5]
        },
        new()
        {
            Id = 4, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian meat sauce over perfectly cooked pasta.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic", "800ml crushed tomatoes", "2 tbsp tomato paste", "Fresh basil", "Olive oil", "Salt and pepper"],
            Steps = ["Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and brown thoroughly.", "Stir in crushed tomatoes and tomato paste.", "Simmer for 20 minutes, season to taste.", "Serve sauce over spaghetti, garnish with basil."],
            Ratings = [5, 5, 4, 5, 5]
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "A decadent dessert with a molten chocolate center.",
            Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour"],
            Steps = ["Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold in melted chocolate mixture, then flour.", "Pour into greased ramekins.", "Bake for 12 minutes — centers should be soft.", "Invert onto plates and serve immediately."],
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Trail Mix Energy Bites", Category = "Snacks",
            Description = "No-bake bites loaded with oats, nuts, and chocolate chips.",
            Ingredients = ["1 cup rolled oats", "½ cup peanut butter", "⅓ cup honey", "½ cup chocolate chips", "½ cup mixed nuts, chopped", "1 tsp vanilla"],
            Steps = ["Mix all ingredients in a large bowl.", "Refrigerate for 30 minutes.", "Roll into 1-inch balls.", "Store in the fridge for up to a week."],
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 7, Title = "Mango Smoothie", Category = "Drinks",
            Description = "A tropical, creamy smoothie bursting with mango flavor.",
            Ingredients = ["1 cup frozen mango chunks", "1 banana", "1 cup yogurt", "½ cup orange juice", "1 tbsp honey"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth and creamy.", "Pour into a glass and serve immediately."],
            Ratings = [5, 4, 5]
        },
        new()
        {
            Id = 8, Title = "Grilled Cheese Sandwich", Category = "Lunch",
            Description = "Crispy, buttery bread with melted gooey cheese inside.",
            Ingredients = ["2 slices white bread", "2 slices cheddar cheese", "1 tbsp butter"],
            Steps = ["Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Cook in a pan over medium heat until golden on each side."],
            Ratings = [5, 4, 4, 5]
        },
    ];

    private int _nextId;

    public RecipeService()
    {
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

