@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@_category?.Icon @CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info mt-3">No recipes found in this category yet.</div>
}
else
{
    <div class="row mt-4">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                            <span class="text-warning">
                                @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++)
                                {
                                    <text>★</text>
                                }
                                <small class="text-muted">(@recipe.RatingCount)</small>
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];
    private RecipeCategory? _category;

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
        _category = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead text-muted">@_recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>

            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in _recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">⭐ Rating</h5></div>
                <div class="card-body text-center">
                    <p class="display-6">@_recipe.AverageRating.ToString("0.0")</p>
                    <p class="text-muted">@_recipe.RatingCount ratings</p>
                    <hr />
                    <p><strong>Rate this recipe:</strong></p>
                    <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@page "/submit"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>📤 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added.</p>
        <a href="recipe/@_submittedId" class="btn btn-primary">View Your Recipe</a>
    </div>
}
else
{
    <EditForm Model="_formModel" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label" for="title">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="_formModel.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="category">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="_formModel.Category">
                        <option value="">-- Select a Category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat.Name">@cat.Icon @cat.Name</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="description">Description</label>
                    <InputTextArea id="description" class="form-control" rows="2" @bind-Value="_formModel.Description" placeholder="A short description of your recipe" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="ingredients">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_formModel.IngredientsText" placeholder="One ingredient per line" />
                    <div class="form-text">Enter one ingredient per line.</div>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="steps">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_formModel.StepsText" placeholder="One step per line" />
                    <div class="form-text">Enter one step per line.</div>
                </div>

                <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
            </div>
        </div>
    </EditForm>
}

@code {
    private RecipeFormModel _formModel = new();
    private bool _submitted;
    private string _title = string.Empty;
    private int _submittedId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _formModel.Title,
            Category = _formModel.Category,
            Description = _formModel.Description,
            Ingredients = _formModel.IngredientsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _formModel.StepsText
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };

        RecipeService.AddRecipe(recipe);
        _title = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        public string Description { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one ingredient.")]
        public string IngredientsText { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one step.")]
        public string StepsText { get; set; } = string.Empty;
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            @onclick="() => Rate(star)"
            @onmouseover="() => _hover = star"
            @onmouseout="() => _hover = 0"
            style="cursor: pointer; font-size: 1.8rem; color: @(star <= (_hover > 0 ? _hover : _selected) ? "#ffc107" : "#ddd");">
            ★
        </span>
    }

    @if (_selected > 0)
    {
        <div class="mt-2">
            <span class="badge bg-success">You rated @_selected star@(_selected > 1 ? "s" : "")!</span>
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _hover;
    private int _selected;

    private void Rate(int rating)
    {
        _selected = rating;
        RecipeService.AddRating(RecipeId, rating);
    }
}

